  ('saalbach-hinterglemm-austria', '01F', 'Saalbach-Hinterglemm', 'Austria', '270 km around the Skicircus, a World Championships pedigree', 'live', 'verified', 'northernLights', 'Austria', '{"ski","nightlife","family","adventure","wellness","entertainment","culinary"}', '{}', '{"essential","comfort","premier","ultra"}', null, 'emerging', '{"key_facts":["Skicircus Saalbach Hinterglemm Leogang Fieberbrunn = ~270 km pistes, ~69 lifts across 4 linked resorts (one of Austria''s largest)","Piste split ~52% easy (140 km) / 41% intermediate (112 km) / 7% difficult (18 km) - a family/intermediate mountain","''The Challenge'' = signature circular tour right around the Skicircus in a day (exact km/vertical to verify)","PROVINCE SEAM: Saalbach/Hinterglemm/Leogang = Salzburg; Fieberbrunn = Tirol (two provinces on one linked pass)","Hosted the FIS Alpine World Ski Championships 2025 (4-16 Feb) - 2nd time after 1991","Elevation 830-2,096 m (top Schattberg ~2,096 m); mid-altitude, backed by strong snowmaking; season ~late Nov-early April","''Best Austrian Apres-Ski'': Bauer''s Schi-Alm, Hinterhag Alm (''Melkstall''), Maisalm, Spitzbub, Der Jennerwein, Bobby''s Pub","Day pass ~EUR 79; Ski ALPIN CARD = up to 408 km with Zell am See-Kaprun + Schmittenhoehe; Epic tag on skiresort.info UNVERIFIED (not asserted); no Ikon","Village ~1,003 m, Glemmtal; deep ski-in/ski-out 4/5-star base; sunny south-facing slopes","Reached via Zell am See rail (~80 km S of Salzburg) + Glemmtal bus; Salzburg/Munich/Innsbruck airports","Fieberbrunn sector = freeride corner (former Freeride World Tour venue - verify)","Heli-skiing NOT available (Austria permits it only at Vorarlberg/Lech-Zurs sites)","Big summer mountain-biking + hiking destination on the same lifts","Nearest hospital = Tauernklinikum Zell am See (verify exact name/status)","Avalanche: Lawinenwarndienst Salzburg for the Salzburg sectors + Lawinenwarndienst Tirol for Fieberbrunn - EAWS 5-level, NOT SLF/Meteo"],"safety":{"emergency":"112 EU general / 140 Bergrettung alpine rescue / 144 ambulance / 133 police / 122 fire","hospital":"Tauernklinikum Zell am See (down-valley, verify); local practice for day cases; 140 Bergrettung / helicopter alpine evac","advisory_level":"L1","malaria":"none","yellow_fever":"not required","activity_note":"Mostly gentle pisted terrain but Fieberbrunn freeride + off-piste carry avalanche risk: check Lawinenwarndienst Salzburg (Salzburg sectors) AND Lawinenwarndienst Tirol/lawinen.report (Fieberbrunn), EAWS 5-level; transceiver/shovel/probe + guide off-piste; heli NOT available (Austria = Vorarlberg only); pace alcohol given apres culture; rescue 140 Bergrettung","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/austria","read":"2026-08-19","page_updated":"2026-08-11T10:19:06+01:00"}},"timing":{"peak":"High winter — Christmas/NY, Feb half-terms, Easter — skiing + apres","shoulder":"Early Dec opening + March-early April spring skiing (sunny slopes)","green":"May-Jun + Oct-Nov (summer hiking/biking season; verify winter-lift ops)","booking_lead":"Christmas/NY + Feb + Easter 3-8 mo; regular winter 2-4 mo; summer 1-3 mo","off_season_specials":"Summer MTB/hiking (big bike destination); spring-ski value; 2025-Worlds legacy profile","event_peaks":"Ski holidays (late Nov-early April), Christmas/NY, Easter (verify live events calendar)","campaign_start":"Next winter + family weeks by Jun-Sep; spring-ski from Jan; ride the 2025-Worlds profile"},"jewels":[{"name":"Ski the 270 km Skicircus on one pass","si_tag":"Winter/Ski","status":"live","tier":"comfort","price_band":"~EUR 79/day pass; instructor ~EUR 350-550/day (approx)","timing":"ski ~late Nov-early April; verify","draw_rank":1,"hook":"four linked resorts and one of Austria''s biggest connected areas on a single ticket","si":"ski","blurb":"four linked resorts and one of Austria''s biggest connected areas on a single ticket","when":"ski ~late Nov-early April; verify","commission":"school/operator 10-15%"}